-- ============================================================================
-- EC9: Joint Ventures, Operating Agreements & Cost Recovery joins the catalogue
-- in the Economics & Commercial module. AN ENGINE COURSE: there is no Suite
-- app; the practicals run in the course's own calculator panels.
--
-- Catalogue row (module 'economics'; path_order 74; prereq_slug NULL,
-- the lead's decision; school left at its default) plus the three capstones and
-- their eighteen graded fields, generated by tools/course-waves/joa/gen_course.py
-- from the ENGINE'S OWN RUN (joa_capstone.mjs through the vendored
-- engines/economics/jointVenture.js, petrolord-engines 3ae56e7), which it
-- refuses to write unless fields.json carries exactly that run's values and the
-- tolerance gradedTolerance.js derives. Deep seeds are three separate
-- migrations; the go-live is a fifth and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/joa.
--
-- WHAT IS GRADED. IDUMU (Associate) grades a carrier's paying interest, two
-- months of one partner's cash calls, an allowed budget overrun and two
-- overhead charges on a marginal scale; OKWELLE (Professional) grades a carry
-- balance with a compound uplift, a PIA s.85(4) back-in refund, default
-- interest compounded monthly and one party's cover, a cash call in the
-- reconciliation ledger and a year's PSC cost recovered; ABIAMA (Expert)
-- grades a non-consent premium and the payout year's receipt, a buy-in part,
-- a carrier's NPV, a year's government profit oil and an interest after
-- forfeiture. Every value is a return value of the engine, identical under
-- every reading the engine states, and the data it was run on is in the case
-- file the prompt names.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('joa', 'Joint Ventures, Operating Agreements & Cost Recovery', 'economics', 74, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'joa', 'beginner', 'associate',
  'IDUMU, the Idumu satellite joint venture (synthetic)',
  'Interests and the joint account',
  'IDUMU, the Idumu satellite joint venture on the Ekene licence (synthetic). One case file comes with this capstone: idumu_case.json carries four calls under the keys interests, cashCalls, budget and overhead; paste it into the account calculator, whose views each read the key they need. The parties are IOP 42.5 percent, KAP 23.75 percent, ZED 18.75 percent, SNP 15 percent; SNP is carried for 80 percent of its cost share, pro rata by the other parties (pro-rata). The cash calls run 2029-03 to 2029-08: the difference of a called month adjusts the call 1 month later (reconciliationLagMonths 1), an adjustment above a forecast share is refunded as a negative call (negativeCall refund), and no cash call is made in a month whose forecast is below 750000 (noCallBelow). The 2029 budget allows each item 10 percent over its approval (itemTolerancePct) and the budget the lower of 4 percent of the approved total and 3500000 (budgetTolerance), with an unbudgeted allowance of 400000. The 2031 overhead is charged on each category''s cost less its stated exclusions (operating 2860000) on a marginal scale: exploration: 2.4 percent up to 25000000, 0 percent above; operating: 2.6 percent up to 50000000, 1.1 percent up to 110000000, 0.5 percent above; development: 2.4 percent up to 60000000, 1.2 percent up to 120000000, 0.6 percent above. No value depends on any of the three readings the engine states (the PSC income tax on the contractor''s profit oil, interest from the due date once a grace is exceeded, the default cover by paying interest), and every term a value needs is stated in the case file: the engine holds no default for any of them. Report six values: ZED''s paying interest while SNP is carried; ZED''s cash call for June 2029; what ZED pays in August 2029; the allowed overrun of the 2029 budget; and the operating and the development overhead charges for 2031. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','idumu_zed_paying_pct', 'label','ZED''s paying interest while SNP is carried', 'unit','percent', 'expected',21.397058823529413, 'tol',5e-07),
    jsonb_build_object('key','idumu_zed_june_call', 'label','ZED''s cash call for June 2029', 'unit','USD', 'expected',1998619.1327205882, 'tol',5e-07),
    jsonb_build_object('key','idumu_zed_august_paid', 'label','What ZED pays in August 2029, its call and any arrears billing', 'unit','USD', 'expected',1979559.8095588237, 'tol',5e-07),
    jsonb_build_object('key','idumu_budget_allowed_overrun', 'label','The allowed overrun of the 2029 budget', 'unit','USD', 'expected',3004000.5, 'tol',5e-07),
    jsonb_build_object('key','idumu_operating_overhead', 'label','The operating overhead charge for 2031', 'unit','USD', 'expected',1471074.75275, 'tol',5e-07),
    jsonb_build_object('key','idumu_development_overhead', 'label','The development overhead charge for 2031', 'unit','USD', 'expected',2261700.0045, 'tol',5e-07)
  )
),
(
  'joa', 'intermediate', 'professional',
  'OKWELLE, the Okwelle gas-condensate joint venture (synthetic)',
  'Recovery, default and cost recovery',
  'OKWELLE, the Okwelle gas-condensate joint venture (synthetic). One case file comes with this capstone: okwelle_case.json carries five calls under the keys carry, cashCalls, backIn, default and psc; paste it into the recovery calculator. The parties are OKO 35 percent, PRA 27.5 percent, PRB 22.5 percent, NCP 15 percent; NCP is carried for 100 percent of its cost share, pro rata by the other parties (pro-rata). The carry is recovered from at most 60 percent of NCP''s share of each year''s entitlement (recoverFromPct), with a compound uplift of 7.5 percent a year on the opening balance (uplift compound), no cap, under the contract''s own terms (basis contract). The cash calls run 2030-01 to 2030-09: the difference of a called month adjusts the call 2 months later (reconciliationLagMonths 2), an adjustment above a forecast share is carried to the next call (negativeCall carry), and no cash call is made in a month whose forecast is below 1000000 (noCallBelow). NCP backs in to 37.5 percent under PIA 2021 s.85(4) (basis pia-s85-4), its refund recovered from 55 percent of its new share of future entitlement (refundForm from-future-entitlement). On the 14650000 cash call due 2030-06-01, PRA pays 1250000.5 and cures on 2030-08-19; default interest at 9.5 percent a year on a 365-day basis, compounded monthly (interestMethod monthly-compound), with a grace of 0 hours (graceHours 0); suspension after 5 working days (working-days) from 2030-06-01, forfeiture after 90 calendar days (calendar-days) from 2030-06-08; no carry is live on that call. The production sharing terms: royalty 10 percent of gross, a cost oil limit of 55 percent of gross revenue (costOilLimitBase gross), a contractor profit share of 45 percent, tax 30 percent, an opening cost pool of 186000000. No value depends on any of the three readings the engine states (the PSC income tax on the contractor''s profit oil, interest from the due date once a grace is exceeded, the default cover by paying interest), and every term a value needs is stated in the case file: the engine holds no default for any of them. Report six values: the carry balance carried out of 2031; the back-in refund PRA receives; the default interest on PRA''s unpaid share; OKO''s cover of the unpaid amount; PRB''s cash call for June 2030; and the cost recovered in 2032 under the PSC. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','okwelle_2031_carry_balance', 'label','The carry balance carried out of 2031', 'unit','USD', 'expected',15499789.491662813, 'tol',5e-07),
    jsonb_build_object('key','okwelle_backin_refund_to_pra', 'label','The back-in refund PRA receives', 'unit','USD', 'expected',29922022.09522059, 'tol',5e-07),
    jsonb_build_object('key','okwelle_default_interest', 'label','The default interest on PRA''s unpaid share', 'unit','USD', 'expected',57396.210640669764, 'tol',5e-07),
    jsonb_build_object('key','okwelle_default_cover_oko', 'label','OKO''s cover of the unpaid amount', 'unit','USD', 'expected',1341465.2758620689, 'tol',5e-07),
    jsonb_build_object('key','okwelle_prb_june_call', 'label','PRB''s cash call for June 2030', 'unit','USD', 'expected',3762105.9485294116, 'tol',5e-07),
    jsonb_build_object('key','okwelle_2032_cost_recovered', 'label','The cost recovered in 2032 under the PSC', 'unit','USD', 'expected',87862500.22000001, 'tol',5e-07)
  )
),
(
  'joa', 'advanced', 'expert',
  'ABIAMA, the Abiama deepwater joint venture (synthetic)',
  'Sole risk, the readings and reading the engine',
  'ABIAMA, the Abiama deepwater joint venture (synthetic). One case file comes with this capstone: abiama_case.json carries five calls under the keys soleRisk, buyIn, carry, psc and default; paste it into the agreement calculator. The parties are ABO 45 percent, SPA 25 percent, SPB 17.5 percent, SNC 12.5 percent. SPB declines the Abiama-3 appraisal sidetrack, and the consenting parties recover 300 percent of its proportionate share of the cost from its share of the operation''s net value (mode recover-from-production). SNC declines the Abiama-4 exploration well and enters it by paying 750 percent of its proportionate share (mode buy-in). SNC is carried for 100 percent of its cost share, pro rata by the other parties (pro-rata), recovered from 100 percent of its share of each year''s entitlement with a multiple uplift of 250 percent of each year''s carried cost (uplift multiple), under the contract''s own terms (basis contract); every party''s net cash flow is discounted at 0.1 to 2031, year-end flows. The production sharing terms: royalty 7.5 percent of gross, a cost oil limit of 62.5 percent of gross revenue (costOilLimitBase gross), a contractor profit share of 50 percent except where a year states its own share in the case file, tax 35 percent, an opening cost pool of 312000000. On the 22800000 cash call due 2034-02-01, SPB pays 1500000.5 and is still in default at 2034-07-15; default interest at 10.25 percent a year on a 360-day basis, simple (interestMethod simple), with a grace of 0 hours (graceHours 0); suspension after 5 working days (working-days) from 2034-02-01, forfeiture after 3 months (months) from 2034-02-12. No value depends on any of the three readings the engine states (the PSC income tax on the contractor''s profit oil, interest from the due date once a grace is exceeded, the default cover by paying interest), and every term a value needs is stated in the case file: the engine holds no default for any of them. Report six values: SPB''s non-consent premium; what SPB receives of its share of the sidetrack''s net value in 2036; SPA''s part of SNC''s buy-in payment; SPA''s NPV under the carry; the government profit oil of 2035; and ABO''s participating interest if SPB''s interest is assigned. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','abiama_spb_premium', 'label','SPB''s non-consent premium', 'unit','USD', 'expected',14043750.21, 'tol',5e-07),
    jsonb_build_object('key','abiama_spb_2036_receipt', 'label','What SPB receives of its share of the sidetrack''s net value in 2036', 'unit','USD', 'expected',1382499.8337499993, 'tol',5e-07),
    jsonb_build_object('key','abiama_buy_in_to_spa', 'label','SPA''s part of SNC''s buy-in payment', 'unit','USD', 'expected',8410714.35267857, 'tol',5e-07),
    jsonb_build_object('key','abiama_spa_carry_npv', 'label','SPA''s NPV under the carry', 'unit','USD', 'expected',128792800.24269654, 'tol',5e-07),
    jsonb_build_object('key','abiama_2035_government_profit_oil', 'label','The government profit oil of 2035', 'unit','USD', 'expected',43938000.13499999, 'tol',5e-07),
    jsonb_build_object('key','abiama_abo_after_forfeiture_pct', 'label','ABO''s participating interest if SPB''s interest is assigned', 'unit','percent', 'expected',54.54545454545455, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
